def _db():
    conn = sqlite3.connect(AUTH_DB)
    conn.row_factory = sqlite3.Row
    conn.execute("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, created_at TEXT NOT NULL, plan TEXT NOT NULL DEFAULT 'Free', plan_expires TEXT, blocked INTEGER NOT NULL DEFAULT 0)")
    conn.execute("CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created_at TEXT NOT NULL)")
    conn.execute("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, plan TEXT NOT NULL, method TEXT NOT NULL, transaction_id TEXT NOT NULL, amount REAL NOT NULL, status TEXT NOT NULL DEFAULT 'pending', submitted_at TEXT NOT NULL, reviewed_at TEXT, note TEXT)")
    conn.execute("CREATE TABLE IF NOT EXISTS signal_usage (user_id INTEGER NOT NULL, usage_date TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id, usage_date))")
    conn.execute("CREATE TABLE IF NOT EXISTS bot_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
    conn.execute("CREATE TABLE IF NOT EXISTS oauth_states (state TEXT PRIMARY KEY, provider TEXT NOT NULL, created_at TEXT NOT NULL)")
    for col, ddl in [("plan", "TEXT NOT NULL DEFAULT 'Free'"), ("plan_expires", "TEXT"), ("blocked", "INTEGER NOT NULL DEFAULT 0")]:
        try: conn.execute(f"ALTER TABLE users ADD COLUMN {col} {ddl}")
        except sqlite3.OperationalError: pass
    conn.commit(); return conn

def _load_persistent_settings():
    """Load dashboard controls from SQLite so deploy/restart does not reset them."""
    try:
        conn=_db(); rows=conn.execute("SELECT key,value FROM bot_settings").fetchall(); conn.close()
        saved={r["key"]: json.loads(r["value"]) for r in rows}
        for key,val in saved.items():
            if key in BOT_SETTINGS:
                BOT_SETTINGS[key]=val
        if isinstance(saved.get("strategy_weights"), dict):
            weights=saved["strategy_weights"]
            for i,(name,_) in enumerate(STRATEGIES):
                if name in weights:
                    STRATEGIES[i]=(name,float(weights[name]))
    except Exception as exc:
        print("Persistent settings load skipped:", exc)


def _save_persistent_settings():
    try:
        conn=_db()
        values={
            "consensus_required": BOT_SETTINGS["consensus_required"],
            "lead_required": BOT_SETTINGS["lead_required"],
            "min_entry_consensus": BOT_SETTINGS["min_entry_consensus"],
            "telegram_enabled": BOT_SETTINGS["telegram_enabled"],
            "auto_refresh_seconds": BOT_SETTINGS["auto_refresh_seconds"],
            "enabled_strategies": BOT_SETTINGS["enabled_strategies"],
            "enabled_markets": BOT_SETTINGS["enabled_markets"],
            "enabled_timeframes": BOT_SETTINGS["enabled_timeframes"],
            "strategy_weights": {name:weight for name,weight in STRATEGIES},
        }
        for k,v in values.items():
            conn.execute("INSERT INTO bot_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",(k,json.dumps(v)))
        conn.commit(); conn.close()
    except Exception as exc:
        print("Persistent settings save skipped:", exc)


_load_persistent_settings()

def _hash_password(password, salt=None):
    salt = salt or secrets.token_hex(16)
    return hashlib.pbkdf2_hmac("sha256", password.encode(), bytes.fromhex(salt), 210000).hex(), salt

def _current_user(request: Request):
    token = request.cookies.get(SESSION_COOKIE)
    if not token: return None
    conn = _db()
    row = conn.execute("SELECT u.id,u.name,u.email,u.plan,u.plan_expires,u.blocked FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=?", (token,)).fetchone()
    if not row:
        conn.close(); return None
    user=dict(row)
    if user["blocked"]:
        conn.execute("DELETE FROM sessions WHERE token=?", (token,)); conn.commit(); conn.close(); return None
    # Expired paid plans automatically fall back to Free.
    if user.get("plan") not in (None, "Free") and user.get("plan_expires"):
        try:
            exp=datetime.fromisoformat(user["plan_expires"].replace("Z","+00:00"))
            if exp <= datetime.now(timezone.utc):
                conn.execute("UPDATE users SET plan='Free', plan_expires=NULL WHERE id=?", (user["id"],))
                conn.commit(); user["plan"]="Free"; user["plan_expires"]=None
        except ValueError: pass
    conn.close(); return user

def _require_user(request: Request):
    user=_current_user(request)
    if not user: raise HTTPException(401,"Login required")
    return user

def _plan_limit(user_id, plan):
    limit=int(PLAN_CONFIG.get(plan, PLAN_CONFIG["Free"])["daily_signals"])
    today=datetime.now(timezone.utc).date().isoformat()
    conn=_db(); row=conn.execute("SELECT count FROM signal_usage WHERE user_id=? AND usage_date=?",(user_id,today)).fetchone(); conn.close()
    used=int(row["count"]) if row else 0
    return used, limit

def _consume_signal(user_id, plan):
    used,limit=_plan_limit(user_id,plan)
    if used>=limit: raise HTTPException(429,f"Daily signal limit reached for {plan} plan ({limit}).")
    today=datetime.now(timezone.utc).date().isoformat(); conn=_db()
    conn.execute("INSERT INTO signal_usage(user_id,usage_date,count) VALUES(?,?,1) ON CONFLICT(user_id,usage_date) DO UPDATE SET count=count+1",(user_id,today)); conn.commit(); conn.close()
    return used+1,limit

@app.get("/auth/me")
def auth_me(request: Request):
    user = _current_user(request)
    if user:
        conn=_db(); row=conn.execute("SELECT plan,plan_expires,blocked FROM users WHERE id=?", (user["id"],)).fetchone(); conn.close(); user.update(dict(row))
    return {"authenticated": bool(user), "user": user, "is_admin": bool(user and ADMIN_EMAIL and user["email"].lower()==ADMIN_EMAIL)}

@app.post("/auth/signup")
async def auth_signup(request: Request, response: Response):
    p = await request.json(); name=str(p.get("name","")).strip(); email=str(p.get("email","")).strip().lower(); password=str(p.get("password",""))
    if len(name)<2: raise HTTPException(400,"Name must be at least 2 characters")
    if "@" not in email: raise HTTPException(400,"Enter a valid email")
    if len(password)<6: raise HTTPException(400,"Password must be at least 6 characters")
    conn=_db(); pw,salt=_hash_password(password)
    try:
        cur=conn.execute("INSERT INTO users(name,email,password_hash,salt,created_at) VALUES(?,?,?,?,?)",(name,email,pw,salt,datetime.now(timezone.utc).isoformat()))
    except sqlite3.IntegrityError:
        conn.close(); raise HTTPException(409,"An account with this email already exists")
    token=secrets.token_urlsafe(32); conn.execute("INSERT INTO sessions(token,user_id,created_at) VALUES(?,?,?)",(token,cur.lastrowid,datetime.now(timezone.utc).isoformat())); conn.commit(); conn.close()
    response.set_cookie(SESSION_COOKIE,token,httponly=True,samesite="lax",secure=_env_bool("COOKIE_SECURE", True),max_age=SESSION_MAX_AGE)
    return {"ok":True,"user":{"name":name,"email":email}}

@app.post("/auth/login")
async def auth_login(request: Request, response: Response):
    p=await request.json(); email=str(p.get("email","")).strip().lower(); password=str(p.get("password","")); conn=_db(); row=conn.execute("SELECT * FROM users WHERE email=?",(email,)).fetchone()
    if not row: conn.close(); raise HTTPException(401,"Invalid email or password")
    if row["blocked"]: conn.close(); raise HTTPException(403,"This account is blocked. Contact Admin.")
    cand,_=_hash_password(password,row["salt"])
    if not hmac.compare_digest(cand,row["password_hash"]): conn.close(); raise HTTPException(401,"Invalid email or password")
    token=secrets.token_urlsafe(32); conn.execute("INSERT INTO sessions(token,user_id,created_at) VALUES(?,?,?)",(token,row["id"],datetime.now(timezone.utc).isoformat())); conn.commit(); conn.close()
    response.set_cookie(SESSION_COOKIE,token,httponly=True,samesite="lax",secure=_env_bool("COOKIE_SECURE", True),max_age=SESSION_MAX_AGE)
    return {"ok":True,"user":{"name":row["name"],"email":row["email"]}}

@app.post("/auth/logout")
def auth_logout(request: Request, response: Response):
    token=request.cookies.get(SESSION_COOKIE)
    if token:
        conn=_db(); conn.execute("DELETE FROM sessions WHERE token=?",(token,)); conn.commit(); conn.close()
    response.delete_cookie(SESSION_COOKIE); return {"ok":True}


@app.get("/auth/google")
def auth_google(request: Request):
    if not GOOGLE_CLIENT_ID:
        raise HTTPException(503,"Google Sign-In is not configured. Add GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET in Railway Variables.")
    redirect_uri=GOOGLE_REDIRECT_URI or str(request.base_url).rstrip("/")+"/auth/google/callback"
    state=secrets.token_urlsafe(32)
    conn=_db(); conn.execute("INSERT INTO oauth_states(state,provider,created_at) VALUES(?,?,?)",(state,"google",datetime.now(timezone.utc).isoformat())); conn.commit(); conn.close()
    params={"client_id":GOOGLE_CLIENT_ID,"redirect_uri":redirect_uri,"response_type":"code","scope":"openid email profile","state":state,"access_type":"offline","prompt":"select_account"}
    from fastapi.responses import RedirectResponse
    return RedirectResponse("https://accounts.google.com/o/oauth2/v2/auth?"+urlencode(params),status_code=302)

@app.get("/auth/google/callback")
async def auth_google_callback(request: Request, response: Response, code: str = "", state: str = "", error: str = ""):
    from fastapi.responses import RedirectResponse
    if error:
        return RedirectResponse("/?auth_error="+urlencode({"error":error}))
    conn=_db(); row=conn.execute("SELECT * FROM oauth_states WHERE state=? AND provider='google'",(state,)).fetchone(); conn.execute("DELETE FROM oauth_states WHERE state=?",(state,)); conn.commit(); conn.close()
    if not row: raise HTTPException(400,"Invalid or expired Google sign-in state")
    try:
        redirect_uri=GOOGLE_REDIRECT_URI or str(request.base_url).rstrip("/")+"/auth/google/callback"
        async with httpx.AsyncClient(timeout=20) as client:
            token_r=await client.post("https://oauth2.googleapis.com/token",data={"code":code,"client_id":GOOGLE_CLIENT_ID,"client_secret":GOOGLE_CLIENT_SECRET,"redirect_uri":redirect_uri,"grant_type":"authorization_code"})
            token=token_r.json()
            if "access_token" not in token: raise ValueError(token.get("error_description") or "Google token exchange failed")
            info_r=await client.get("https://openidconnect.googleapis.com/v1/userinfo",headers={"Authorization":"Bearer "+token["access_token"]})
            info=info_r.json()
        email=str(info.get("email","")).strip().lower(); name=str(info.get("name") or info.get("given_name") or "Google User").strip()
        if not email: raise ValueError("Google did not return an email address")
        conn=_db(); user=conn.execute("SELECT * FROM users WHERE email=?",(email,)).fetchone()
        if user and user["blocked"]: conn.close(); raise HTTPException(403,"This account is blocked. Contact Admin.")
        if user:
            uid=user["id"]
            if user["name"] != name and name: conn.execute("UPDATE users SET name=? WHERE id=?",(name,uid))
        else:
            pw,salt=_hash_password(secrets.token_urlsafe(24)); cur=conn.execute("INSERT INTO users(name,email,password_hash,salt,created_at) VALUES(?,?,?,?,?)",(name,email,pw,salt,datetime.now(timezone.utc).isoformat())); uid=cur.lastrowid
        session=secrets.token_urlsafe(32); conn.execute("INSERT INTO sessions(token,user_id,created_at) VALUES(?,?,?)",(session,uid,datetime.now(timezone.utc).isoformat())); conn.commit(); conn.close()
        out=RedirectResponse("/",status_code=302); out.set_cookie(SESSION_COOKIE,session,httponly=True,samesite="lax",secure=_env_bool("COOKIE_SECURE", True),max_age=SESSION_MAX_AGE); return out
    except HTTPException: raise
    except Exception as exc:
        raise HTTPException(502,f"Google sign-in failed: {exc}")


def market_is_open(symbol: str, now_utc=None):
    symbol = symbol.replace("/", "").upper()
    m = MARKET_CATALOG.get(symbol)
    if not m:
        return False
    now_utc = now_utc or datetime.now(timezone.utc)
    kind = m["type"]
    if kind == "CRYPTO":
        return True
    if kind == "FX":
        # Standard spot-FX weekly session: Sunday 22:00 UTC to Friday 22:00 UTC.
        wd = now_utc.weekday()
        mins = now_utc.hour * 60 + now_utc.minute
        if wd == 5:
            return False
        if wd == 6:
            return mins >= 22 * 60
        if wd == 4:
            return mins < 22 * 60
        return True
    if kind == "COMMODITY":
        # Major spot/futures commodities are treated as weekday electronic sessions;
        # exact exchange holidays/halts remain provider/exchange dependent.
        wd = now_utc.weekday()
        mins = now_utc.hour * 60 + now_utc.minute
        if wd == 5:
            return False
        if wd == 6:
            return mins >= 22 * 60
        if wd == 4:
            return mins < 22 * 60
        return True
    tz = ZoneInfo(m["tz"])
    local = now_utc.astimezone(tz)
    if local.weekday() >= 5:
        return False
    cur = local.hour * 60 + local.minute + local.second / 60
    for op, cl in m["hours"]:
        oh, om = map(int, op.split(":")); ch, cm = map(int, cl.split(":"))
        if oh * 60 + om <= cur < ch * 60 + cm:
            return True
    return False


def market_label(symbol: str):
    m = MARKET_CATALOG[symbol]
    return f"{m['name']} • {m['type']}"


def open_markets():
    return [s for s in MARKETS if BOT_SETTINGS["enabled_markets"].get(s, True) and market_is_open(s)]


MARKET_STATS_CACHE = {"ts": 0.0, "data": []}


def _market_change_pct(frame):
    try:
        closes=pd.to_numeric(frame["close"],errors="coerce").dropna()
        if len(closes)<2 or float(closes.iloc[-2])==0: return None
        return round((float(closes.iloc[-1])-float(closes.iloc[-2]))/float(closes.iloc[-2])*100,3)
    except Exception: return None


async def get_market_stats():
    """Return open/closed status only. Do NOT fetch candles for every market.
    This prevents dashboard refreshes from burning through provider API credits."""
    stats=[]
    for symbol in MARKETS:
        if not BOT_SETTINGS["enabled_markets"].get(symbol,True):
            continue
        is_open=market_is_open(symbol)
        stats.append({"symbol":symbol,"label":MARKET_CATALOG[symbol]["name"],"name":MARKET_CATALOG[symbol]["name"],"type":MARKET_CATALOG[symbol]["type"],"open":is_open,"status":"OPEN" if is_open else "CLOSED","change_pct":None})
    stats.sort(key=lambda x:(not x["open"],x["name"]))
    return stats

    symbols = [s for s in MARKETS if BOT_SETTINGS["enabled_markets"].get(s, True)]

    async def one(symbol):
        is_open = market_is_open(symbol)
        base = {
            "symbol": symbol,
            "label": market_label(symbol),
            "name": MARKET_CATALOG[symbol]["name"],
            "type": MARKET_CATALOG[symbol]["type"],
            "open": is_open,
            "status": "OPEN" if is_open else "CLOSED",
            "change_pct": None,
        }
        if not is_open:
            return base
        try:
            frame = await get_fx_data(symbol, "1min")
            base["change_pct"] = _market_change_pct(frame)
        except HTTPException as exc:
            base["error"] = str(exc.detail)
        except Exception as exc:
            base["error"] = str(exc)
        return base

    data = await asyncio.gather(*(one(x) for x in symbols))
    data.sort(key=lambda x: (not x["open"], x["name"]))
    MARKET_STATS_CACHE.update(ts=now, data=list(data))
    return MARKET_STATS_CACHE["data"]


# Cache for real candle data to reduce Twelve Data credit usage.
# The cache is keyed by symbol/timeframe and refreshes at most once per minute.
FX_DATA_CACHE = {}
FX_CACHE_TTL_SECONDS = max(60, int(os.getenv("FX_CACHE_TTL_SECONDS", "60")))


async def get_fx_data(symbol: str, timeframe: str = "1min") -> pd.DataFrame:
    """Fetch real FX candles while avoiding repeated Twelve Data requests.

    The returned candles are never synthetic. A short-lived in-process cache is
    used so repeated dashboard refreshes/Telegram requests do not consume a new
    Twelve Data credit when the same symbol/timeframe was fetched recently.
    """
    import time

    symbol = symbol.replace("/", "").upper()
    if symbol not in MARKET_CATALOG:
        raise HTTPException(400, "Unsupported market.")
    if timeframe not in TIMEFRAMES:
        raise HTTPException(400, "Choose 1min, 5min, 15min, 30min or 60min.")
    if not BOT_SETTINGS["enabled_timeframes"].get(timeframe, True):
        raise HTTPException(403, f"{timeframe} is disabled in Settings.")
    market_type=MARKET_CATALOG[symbol]["type"]
    cache_key = (symbol, timeframe)
    if market_type == "CRYPTO":
        import time
        now=time.time(); cached=FX_DATA_CACHE.get(cache_key)
        if cached and now-cached["ts"] < FX_CACHE_TTL_SECONDS:
            return cached["frame"].copy()
        pair=MARKET_CATALOG[symbol]["provider"].replace("/","").upper()+"T" if not MARKET_CATALOG[symbol]["provider"].upper().endswith("USDT") else MARKET_CATALOG[symbol]["provider"].replace("/","").upper()
        # Real 24/7 Binance spot candles; no API key and no synthetic prices.
        interval=timeframe.replace("min","m").replace("60m","1h")
        try:
            async with httpx.AsyncClient(timeout=20) as client:
                response=await client.get("https://api.binance.com/api/v3/klines",params={"symbol":pair,"interval":interval,"limit":250})
            data=response.json()
            if not isinstance(data,list): raise ValueError(data.get("msg","Binance returned no candles"))
            frame=pd.DataFrame([{
                "time":datetime.fromtimestamp(x[0]/1000,timezone.utc).isoformat(),
                "open":float(x[1]),"high":float(x[2]),"low":float(x[3]),"close":float(x[4])
            } for x in data])
        except Exception as exc:
            if cached: return cached["frame"].copy()
            raise HTTPException(502,f"Crypto real-data connection failed: {type(exc).__name__}: {exc}")
        if len(frame)<80: raise HTTPException(502,f"Crypto provider returned only {len(frame)} candles; at least 80 are needed.")
        FX_DATA_CACHE[cache_key]={"ts":now,"frame":frame.copy()}
        return frame
    if not TWELVE_DATA_API_KEY:
        raise HTTPException(503,"Real intraday data is not configured. Add TWELVE_DATA_API_KEY in Railway Variables, then redeploy.")

    if market_type not in {"FX","INDEX","COMMODITY"}:
        raise HTTPException(503,"This market has no configured real intraday data source.")

    now = time.time()
    cached = FX_DATA_CACHE.get(cache_key)
    if cached and now - cached["ts"] < FX_CACHE_TTL_SECONDS:
        return cached["frame"].copy()

    try:
        async with httpx.AsyncClient(timeout=30) as client:
            response = await client.get(
                "https://api.twelvedata.com/time_series",
                params={
                    "symbol": MARKET_CATALOG[symbol]["provider"],
                    "interval": timeframe,
                    "outputsize": 250,
                    "apikey": TWELVE_DATA_API_KEY,
                    "format": "JSON",
                },
            )
        data = response.json()
    except Exception as exc:
        # If a previous real cache exists, keep the bot usable rather than
        # fabricating prices.
        if cached:
            return cached["frame"].copy()
        raise HTTPException(502, f"Market data connection failed: {type(exc).__name__}: {exc}")

    if "values" not in data:
        msg = data.get("message") or data.get("code") or data.get("status") or "No candle data returned by Twelve Data."
        if cached:
            return cached["frame"].copy()
        raise HTTPException(502, f"Twelve Data error: {msg}")

    try:
        frame = pd.DataFrame([
            {"time": x["datetime"], "open": float(x["open"]),
             "high": float(x["high"]), "low": float(x["low"]),
             "close": float(x["close"])}
            for x in data["values"]
        ]).sort_values("time").reset_index(drop=True)
    except Exception as exc:
        raise HTTPException(502, f"Invalid candle data returned by provider: {exc}")

    if len(frame) < 80:
        raise HTTPException(502, f"Provider returned only {len(frame)} candles; at least 80 are needed for the 35-strategy analysis.")

    FX_DATA_CACHE[cache_key] = {"ts": now, "frame": frame.copy()}
    return frame


def indicators(df):
    df = df.copy()
    o, c, h, l = df.open, df.close, df.high, df.low

    for n in [9, 12, 21, 26, 50]:
        df[f"ema{n}"] = c.ewm(span=n, adjust=False).mean()
    for n in [20, 50]:
        df[f"sma{n}"] = c.rolling(n).mean()

    delta = c.diff()
    gain = delta.clip(lower=0).rolling(14).mean()
    loss = (-delta.clip(upper=0)).rolling(14).mean()
    df["rsi"] = 100 - 100 / (1 + gain / loss.replace(0, 1e-12))

    df["macd"] = df.ema12 - df.ema26
    df["macd_signal"] = df.macd.ewm(span=9, adjust=False).mean()
    df["macd_hist"] = df.macd - df.macd_signal

    mid = c.rolling(20).mean()
    sd = c.rolling(20).std()
    df["bb_mid"] = mid
    df["bb_upper"] = mid + 2 * sd
    df["bb_lower"] = mid - 2 * sd

    lo, hi = l.rolling(14).min(), h.rolling(14).max()
    df["stoch"] = 100 * (c - lo) / (hi - lo).replace(0, 1e-12)
    df["stoch_d"] = df.stoch.rolling(3).mean()

    sr_lo, sr_hi = df.stoch.rolling(14).min(), df.stoch.rolling(14).max()
    df["stoch_rsi"] = 100 * (df.stoch - sr_lo) / (sr_hi - sr_lo).replace(0, 1e-12)

    tp = (h + l + c) / 3
    df["cci"] = (tp - tp.rolling(20).mean()) / (
        0.015 * tp.rolling(20).std()
    ).replace(0, 1e-12)

    df["williams"] = -100 * (hi - c) / (hi - lo).replace(0, 1e-12)
    df["roc"] = c.pct_change(12) * 100
    df["momentum"] = c - c.shift(10)

    tr = pd.concat(
        [h - l, (h - c.shift()).abs(), (l - c.shift()).abs()],
        axis=1,
    ).max(axis=1)
    df["atr"] = tr.rolling(14).mean()

    up, down = h.diff(), -l.diff()
    plus = up.where((up > down) & (up > 0), 0.0)
    minus = down.where((down > up) & (down > 0), 0.0)
    atr = df.atr.replace(0, 1e-12)

    pdi = 100 * plus.rolling(14).mean() / atr
    mdi = 100 * minus.rolling(14).mean() / atr
    dx = 100 * (pdi - mdi).abs() / (pdi + mdi).replace(0, 1e-12)

    df["adx"], df["pdi"], df["mdi"] = dx.rolling(14).mean(), pdi, mdi
    df["don_hi"] = h.shift(1).rolling(20).max()
    df["don_lo"] = l.shift(1).rolling(20).min()
    df["tenkan"] = (h.rolling(9).max() + l.rolling(9).min()) / 2
    df["kijun"] = (h.rolling(26).max() + l.rolling(26).min()) / 2
    df["sar_proxy"] = df.ema21 - 2 * df.atr
    df["flow_proxy"] = c.diff().abs().rolling(10).mean()

    # Demand/Supply zones: recent swing-based proxy zones.
    df["demand_low"] = l.shift(1).rolling(20).min()
    df["demand_high"] = df["demand_low"] + df["atr"] * 0.60
    df["supply_high"] = h.shift(1).rolling(20).max()
    df["supply_low"] = df["supply_high"] - df["atr"] * 0.60

    # MMC / Market-Maker-Concept proxy: liquidity sweep + displacement.
    df["prior_high"] = h.shift(1).rolling(10).max()
    df["prior_low"] = l.shift(1).rolling(10).min()
    df["bull_sweep"] = (l < df["prior_low"]) & (c > df["prior_low"]) & (c > o)
    df["bear_sweep"] = (h > df["prior_high"]) & (c < df["prior_high"]) & (c < o)

    return df


def calculate_votes(frame):
    df = indicators(frame).dropna().reset_index(drop=True)
    if len(df) < 60:
        raise HTTPException(502, "Not enough candles.")

    b, p = df.iloc[-1], df.iloc[-2]
    out = []

    def add(i, vote, reason):
        name, weight = STRATEGIES[i]
        if not BOT_SETTINGS["enabled_strategies"].get(name, True):
            vote = "NEUTRAL"
            reason = "Disabled in Settings"
            weight = 0
        out.append({
            "strategy": name,
            "weight": weight,
            "vote": vote,
            "reason": reason,
            "enabled": BOT_SETTINGS["enabled_strategies"].get(name, True),
        })

    add(0, "BUY" if b.rsi < 30 else "SELL" if b.rsi > 70 else "NEUTRAL", f"RSI {b.rsi:.1f}")
    add(1, "BUY" if b.macd > b.macd_signal else "SELL", "MACD")
    add(2, "BUY" if b.ema9 > b.ema21 else "SELL", "EMA 9/21")
    add(3, "BUY" if b.ema21 > b.ema50 else "SELL", "EMA 21/50")
    add(4, "BUY" if b.adx >= 20 and b.pdi > b.mdi else "SELL" if b.adx >= 20 else "NEUTRAL", f"ADX {b.adx:.1f}")
    add(5, "BUY" if b.sma20 > b.sma50 else "SELL", "SMA")
    add(6, "BUY" if b.close <= b.bb_lower else "SELL" if b.close >= b.bb_upper else "BUY" if b.close > b.bb_mid else "SELL", "Bollinger")
    add(7, "BUY" if b.stoch < 20 else "SELL" if b.stoch > 80 else "BUY" if b.stoch > b.stoch_d else "SELL", "Stochastic")
    add(8, "BUY" if b.stoch_rsi < 20 else "SELL" if b.stoch_rsi > 80 else "BUY" if b.stoch_rsi > 50 else "SELL", "Stoch RSI")
    add(9, "BUY" if b.cci > 0 else "SELL", "CCI")
    add(10, "BUY" if b.williams > -50 else "SELL", "Williams %R")
    add(11, "BUY" if b.roc > 0 else "SELL", "ROC")
    add(12, "BUY" if b.momentum > 0 else "SELL", "Momentum")

    atr_avg = df.atr.rolling(30).mean().iloc[-1]
    add(13, "NEUTRAL" if b.atr > atr_avg * 1.8 else "BUY" if b.close > b.ema21 else "SELL", "ATR regime")
    add(14, "BUY" if b.close > b.ema21 else "SELL", "Price vs EMA")
    add(15, "BUY" if b.macd_hist > 0 else "SELL", "Histogram")
    add(16, "BUY" if b.close > b.don_hi else "SELL" if b.close < b.don_lo else "BUY" if b.close > df.close.iloc[-21:-1].mean() else "SELL", "Donchian")
    add(17, "BUY" if b.close > b.sar_proxy else "SELL", "SAR proxy")
    add(18, "BUY" if b.tenkan > b.kijun else "SELL", "Ichimoku proxy")
    add(19, "BUY" if b.close > p.close and b.flow_proxy > df.flow_proxy.rolling(10).mean().iloc[-1] else "SELL", "Flow proxy")
    add(20, "BUY" if b.close > b.open else "SELL", "Candle")
    add(21, "BUY" if b.close > df.close.iloc[-6] else "SELL", "5-bar")
    add(22, "BUY" if b.close > df.close.iloc[-11] else "SELL", "10-bar")

    support = df.low.iloc[-21:-1].min()
    resistance = df.high.iloc[-21:-1].max()
    add(23, "BUY" if b.close <= support * 1.001 else "SELL" if b.close >= resistance * 0.999 else "BUY" if b.close > (support + resistance) / 2 else "SELL", "S/R")
    add(24, "BUY" if b.ema9 > b.ema21 > b.ema50 and b.close > b.ema9 else "SELL" if b.ema9 < b.ema21 < b.ema50 and b.close < b.ema9 else "NEUTRAL", "Alignment")

    # 25 — Demand/Supply zone reaction.
    ds_buy = b.close <= b.demand_high and b.close >= b.demand_low
    ds_sell = b.close >= b.supply_low and b.close <= b.supply_high
    add(25, "BUY" if ds_buy and not ds_sell else "SELL" if ds_sell and not ds_buy else "NEUTRAL", "Demand/Supply zone")

    # 26 — MMC/liquidity-sweep proxy.
    add(26, "BUY" if bool(b.bull_sweep) else "SELL" if bool(b.bear_sweep) else "NEUTRAL", "MMC liquidity sweep")

    # 27 — RSI trend confirmation.
    add(27, "BUY" if b.rsi > 50 and b.close > b.ema21 else "SELL" if b.rsi < 50 and b.close < b.ema21 else "NEUTRAL", "RSI + trend")
    # 28 — MACD trend confirmation.
    add(28, "BUY" if b.macd > b.macd_signal and b.ema9 > b.ema21 else "SELL" if b.macd < b.macd_signal and b.ema9 < b.ema21 else "NEUTRAL", "MACD + EMA")
    # 29 — EMA momentum confirmation.
    add(29, "BUY" if b.ema9 > b.ema21 and b.close > p.close else "SELL" if b.ema9 < b.ema21 and b.close < p.close else "NEUTRAL", "EMA momentum")
    # 30 — Volatility compression / expansion filter.
    bb_width = (b.bb_upper - b.bb_lower) / max(abs(b.bb_mid), 1e-12)
    bb_avg = ((df.bb_upper - df.bb_lower) / df.bb_mid.abs().replace(0, 1e-12)).rolling(20).mean().iloc[-1]
    add(30, "BUY" if bb_width > bb_avg and b.close > b.bb_mid else "SELL" if bb_width > bb_avg and b.close < b.bb_mid else "NEUTRAL", "Volatility expansion")
    # 31 — Multi-bar breakout.
    add(31, "BUY" if b.close > df.high.iloc[-6:-1].max() else "SELL" if b.close < df.low.iloc[-6:-1].min() else "NEUTRAL", "5-bar breakout")
    # 32 — Mean reversion filter.
    add(32, "BUY" if b.rsi < 35 and b.close < b.ema21 else "SELL" if b.rsi > 65 and b.close > b.ema21 else "NEUTRAL", "Mean reversion")
    # 33 — Trend strength filter.
    add(33, "BUY" if b.adx >= 25 and b.pdi > b.mdi and b.ema21 > b.ema50 else "SELL" if b.adx >= 25 and b.mdi > b.pdi and b.ema21 < b.ema50 else "NEUTRAL", "Trend strength")
    # 34 — Liquidity + trend confirmation.
    add(34, "BUY" if bool(b.bull_sweep) and b.ema9 > b.ema21 else "SELL" if bool(b.bear_sweep) and b.ema9 < b.ema21 else "NEUTRAL", "Liquidity + trend")

    return out


async def get_news(symbol):
    if not ALPHA_VANTAGE_API_KEY:
        return {"status": "UNAVAILABLE", "sentiment": "NEUTRAL", "score": 0, "count": 0}

    try:
        async with httpx.AsyncClient(timeout=30) as client:
            r = await client.get(
                "https://www.alphavantage.co/query",
                params={
                    "function": "NEWS_SENTIMENT",
                    "tickers": symbol,
                    "limit": 20,
                    "apikey": ALPHA_VANTAGE_API_KEY,
                },
            )

        feed = r.json().get("feed", [])
        scores = [float(x.get("overall_sentiment_score", 0)) for x in feed]
        avg = sum(scores) / len(scores) if scores else 0

        return {
            "status": "AVAILABLE",
            "sentiment": "BULLISH" if avg >= 0.15 else "BEARISH" if avg <= -0.15 else "NEUTRAL",
            "score": round(avg, 3),
            "count": len(feed),
        }
    except Exception as exc:
        return {"status": "ERROR", "sentiment": "NEUTRAL", "score": 0, "count": 0, "error": str(exc)}


async def make_signal(symbol, timeframe="1min", mode="REAL"):
    # A blank/disabled browser selection must never reach the provider as an
    # "unsupported market". Fall back to the first configured real market.
    symbol = (symbol or "EURUSD").replace("/", "").strip().upper()
    if not symbol:
        symbol = "EURUSD"
    mode = mode.upper()

    if mode == "OTC":
        raise HTTPException(
            503,
            "OTC DATA UNAVAILABLE: connected OTC price feed is required. "
            "No fake OTC price/signal is generated."
        )
    if symbol not in MARKET_CATALOG:
        raise HTTPException(400, "Unsupported market.")
    if not BOT_SETTINGS["enabled_markets"].get(symbol, True):
        raise HTTPException(403, f"{market_label(symbol)} is disabled in Settings.")
    if not market_is_open(symbol):
        raise HTTPException(409, f"{market_label(symbol)} is currently CLOSED.")
    if timeframe not in TIMEFRAMES:
        raise HTTPException(400, "Choose 1min, 5min, 15min, 30min or 60min.")

    frame = await get_fx_data(symbol, timeframe)
    votes = calculate_votes(frame)

    buy = sum(x["vote"] == "BUY" for x in votes)
    sell = sum(x["vote"] == "SELL" for x in votes)
    active_count = sum(1 for x in votes if x.get("enabled", True))
    neutral = STRATEGY_COUNT - buy - sell
    buy_weight = sum(x["weight"] for x in votes if x["vote"] == "BUY")
    sell_weight = sum(x["weight"] for x in votes if x["vote"] == "SELL")

    news = await get_news(symbol)
    # Entry quality filter:
    # NEVER enter when weighted consensus is below 70% for the current candle.
    weighted_consensus = max(buy_weight, sell_weight)
    MIN_ENTRY_CONSENSUS = BOT_SETTINGS["min_entry_consensus"]
    required_votes = min(BOT_SETTINGS["consensus_required"], max(1, active_count))
    lead_required = BOT_SETTINGS["lead_required"]
    conflict = (buy >= required_votes and news["sentiment"] == "BEARISH") or (sell >= required_votes and news["sentiment"] == "BULLISH")

    lead = abs(buy - sell)
    if weighted_consensus < MIN_ENTRY_CONSENSUS:
        action = "AVOID"
        avoid_reason = f"Consensus {weighted_consensus}% is below the {MIN_ENTRY_CONSENSUS:g}% entry threshold."
    elif buy >= required_votes and buy > sell and lead >= lead_required and not conflict:
        action = "BUY"
        avoid_reason = ""
    elif sell >= required_votes and sell > buy and lead >= lead_required and not conflict:
        action = "SELL"
        avoid_reason = ""
    else:
        action = "AVOID"
        avoid_reason = "Vote/lead/news filter did not pass."

    now = datetime.now(BANGLADESH_TZ)
    entry = now.replace(second=0, microsecond=0)
    expiry = entry + timedelta(minutes=TIMEFRAMES[timeframe])
    price = round(float(frame.close.iloc[-1]), 6)

    return {
        "symbol": symbol, "market_name": MARKET_CATALOG[symbol]["name"],
        "market_type": MARKET_CATALOG[symbol]["type"], "mode": mode, "timeframe": timeframe,
        "action": action, "buy_votes": buy, "sell_votes": sell,
        "neutral_votes": neutral, "buy_weight": buy_weight,
        "sell_weight": sell_weight,
        "weighted_consensus": weighted_consensus,
        "min_entry_consensus": MIN_ENTRY_CONSENSUS,
        "avoid_reason": avoid_reason,
        "required_votes": required_votes, "lead_required": lead_required, "active_strategies": active_count, "news": news,
        "price": price, "entry_price": price,
        "entry_time_utc6": entry.strftime("%Y-%m-%d %H:%M:%S"),
        "expiry_time_utc6": expiry.strftime("%Y-%m-%d %H:%M:%S"),
        "timezone": "UTC+6", "updated_at": now.isoformat(),
        "future_candidate": {
            "label": "NEXT CANDLE CANDIDATE",
            "action": action,
            "entry_time_utc6": expiry.strftime("%Y-%m-%d %H:%M:%S"),
            "confidence": weighted_consensus,
            "note": "Candidate based on the latest completed candle; not a guaranteed future price prediction."
        },
        "strategies": votes,
    }



async def telegram_send(chat_id, message):
    if not TELEGRAM_TOKEN or not chat_id:
        return False
    async with httpx.AsyncClient(timeout=20) as client:
        r = await client.post(
            f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendMessage",
            json={"chat_id": chat_id, "text": message},
        )
        return r.is_success


def telegram_signal_message(x):
    return (
        f"🤖 SK BOT SIGNAL\n\n"
        f"📊 {x['symbol']} | {x['timeframe']} | {x['mode']}\n"
        f"🎯 SIGNAL: {x['action']}\n\n"
        f"🟢 BUY {x['buy_votes']}/{len(STRATEGIES)}\n"
        f"🔴 SELL {x['sell_votes']}/{len(STRATEGIES)}\n"
        f"⚪ NEUTRAL {x['neutral_votes']}/{len(STRATEGIES)}\n"
        f"⚖️ Weight {x['weighted_consensus']}%\n"
        f"📰 News {x['news']['sentiment']}\n"
        f"💰 Entry Price: {x['entry_price']}\n"
        f"🕐 Entry UTC+6: {x['entry_time_utc6']}\n"
        f"⏳ Expiry UTC+6: {x['expiry_time_utc6']}\n\n"
        "⚠️ Weight is model importance, not guaranteed accuracy or profit."
    )


async def telegram_polling():
    if not TELEGRAM_TOKEN:
        return

    offset = 0
    async with httpx.AsyncClient(timeout=40) as client:
        while True:
            try:
                r = await client.get(
                    f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/getUpdates",
                    params={"timeout": 30, "offset": offset},
                )
                data = r.json()

                for update in data.get("result", []):
                    offset = update["update_id"] + 1
                    message = update.get("message", {})
                    chat_id = message.get("chat", {}).get("id")
                    text = (message.get("text") or "").strip()
                    if not chat_id:
                        continue

                    if text.startswith("/start"):
                        await telegram_send(
                            chat_id,
                            "🤖 SK BOT ONLINE\n\n{len(STRATEGIES)} strategies enabled.\n"
                            "Signal requires the configured consensus and at least 70% weighted consensus; otherwise AVOID.\n\n"
                            "/signal EURUSD 1min\n"
                            "/signal EURUSD 5min\n"
                            "/signal EURUSD 15min\n"
                            "/signal EURUSD 30min\n"
                            "/signal EURUSD 60min\n"
                            "/markets"
                        )
                    elif text.startswith("/markets"):
                        await telegram_send(
                            chat_id,
                            "🟢 OPEN NOW\n" + (", ".join(open_markets()) or "No scheduled market") +
                            "\n\n📚 Total catalog: " + str(len(MARKETS)) +
                            "\nTimeframes: 1min, 5min, 15min, 30min, 60min"
                        )
                    elif text.startswith("/chatid"):
                        await telegram_send(chat_id, f"🆔 Your Telegram Chat ID: {chat_id}\n\nAdd this value to Render as TELEGRAM_CHAT_ID to receive web-dashboard signals here.")
                    elif text.startswith("/signal"):
                        parts = text.split()
                        symbol = parts[1] if len(parts) > 1 else "EURUSD"
                        timeframe = parts[2] if len(parts) > 2 else "1min"
                        try:
                            x = await make_signal(symbol, timeframe, "REAL")
                            await telegram_send(chat_id, telegram_signal_message(x))
                        except Exception as exc:
                            await telegram_send(chat_id, f"❌ {exc}")
                    else:
                        await telegram_send(chat_id, "Use /signal EURUSD 1min or /markets")

            except Exception as exc:
                print("Telegram error:", exc)
                await asyncio.sleep(5)



