@app.post("/payments/submit")
async def submit_payment(request: Request):
    user=_require_user(request); p=await request.json()
    plan=str(p.get("plan","")); method=str(p.get("method","")); tx=str(p.get("transaction_id","")).strip()
    if plan not in PLAN_CONFIG or plan=="Free": raise HTTPException(400,"Choose a paid plan")
    if method not in PAYMENT_INFO: raise HTTPException(400,"Invalid payment method")
    if len(tx)<3: raise HTTPException(400,"Enter a valid transaction ID / payment reference")
    amount=float(PLAN_CONFIG[plan]["price"])
    conn=_db(); cur=conn.execute("INSERT INTO payments(user_id,plan,method,transaction_id,amount,status,submitted_at) VALUES(?,?,?,?,?,?,?)",(user["id"],plan,method,tx,amount,"pending",datetime.now(timezone.utc).isoformat())); conn.commit(); pid=cur.lastrowid; conn.close()
    return {"ok":True,"payment_id":pid,"status":"pending","message":"Payment submitted. Admin approval is required."}

