def _require_admin(request: Request):
    user = _current_user(request)
    if not user or not ADMIN_EMAIL or user["email"].lower() != ADMIN_EMAIL:
        raise HTTPException(403, "Admin access required")
    return user

@app.get("/admin/api/overview")
def admin_overview(request: Request):
    _require_admin(request)
    conn=_db()
    total=conn.execute("SELECT COUNT(*) c FROM users").fetchone()["c"]
    blocked=conn.execute("SELECT COUNT(*) c FROM users WHERE blocked=1").fetchone()["c"]
    active=conn.execute("SELECT COUNT(*) c FROM users WHERE blocked=0").fetchone()["c"]
    users=conn.execute("SELECT id,name,email,created_at,plan,plan_expires,blocked FROM users ORDER BY id DESC").fetchall()
    conn.close()
    return {"total":total,"active":active,"blocked":blocked,"users":[dict(x) for x in users]}

@app.post("/admin/api/user/{user_id}")
async def admin_update_user(user_id:int, request:Request):
    _require_admin(request)
    p=await request.json(); conn=_db()
    row=conn.execute("SELECT id FROM users WHERE id=?",(user_id,)).fetchone()
    if not row: conn.close(); raise HTTPException(404,"User not found")
    if "blocked" in p: conn.execute("UPDATE users SET blocked=? WHERE id=?",(1 if p["blocked"] else 0,user_id))
    if "plan" in p: conn.execute("UPDATE users SET plan=? WHERE id=?",(str(p["plan"])[:40],user_id))
    if "plan_expires" in p: conn.execute("UPDATE users SET plan_expires=? WHERE id=?",(p["plan_expires"] or None,user_id))
    conn.commit(); conn.close(); return {"ok":True}

@app.get("/admin/api/payments")
def admin_payments(request: Request):
    _require_admin(request); conn=_db(); rows=conn.execute("SELECT p.*,u.name,u.email FROM payments p JOIN users u ON u.id=p.user_id ORDER BY p.id DESC LIMIT 200").fetchall(); conn.close(); return {"payments":[dict(r) for r in rows]}

@app.post("/admin/api/payment/{payment_id}")
async def admin_payment(payment_id:int, request:Request):
    _require_admin(request); p=await request.json(); status=str(p.get("status",""))
    if status not in {"approved","rejected"}: raise HTTPException(400,"Invalid payment status")
    conn=_db(); row=conn.execute("SELECT * FROM payments WHERE id=?",(payment_id,)).fetchone()
    if not row: conn.close(); raise HTTPException(404,"Payment not found")
    now=datetime.now(timezone.utc).isoformat()
    if status=="approved":
        days=int(PLAN_CONFIG[row["plan"]]["days"]); exp=(datetime.now(timezone.utc)+timedelta(days=days)).isoformat()
        conn.execute("UPDATE users SET plan=?,plan_expires=? WHERE id=?",(row["plan"],exp,row["user_id"]))
    conn.execute("UPDATE payments SET status=?,reviewed_at=? WHERE id=?",(status,now,payment_id)); conn.commit(); conn.close(); return {"ok":True}

