ADVANCED_ENGINE_VERSION = "2.0"
ADVANCED_MIN_STRUCTURE_SCORE = 60.0
ADVANCED_MIN_ENTRY_SCORE = 60.0
ADVANCED_MIN_RISK_REWARD = 1.5

def _safe_float(v, default=0.0):
    try:
        return float(v)
    except Exception:
        return default

def advanced_signal_gate(structure_score, trend_score, momentum_score,
                         entry_score, volatility_score, risk_reward):
    """Return a conservative final gate for the advanced engine."""
    scores = [
        _safe_float(structure_score),
        _safe_float(trend_score),
        _safe_float(momentum_score),
        _safe_float(entry_score),
        _safe_float(volatility_score),
    ]
    if _safe_float(structure_score) < ADVANCED_MIN_STRUCTURE_SCORE:
        return False
    if _safe_float(entry_score) < ADVANCED_MIN_ENTRY_SCORE:
        return False
    if _safe_float(risk_reward) < ADVANCED_MIN_RISK_REWARD:
        return False
    return sum(scores) / len(scores) >= 60.0

